#!/usr/bin/env python3
"""
Base Converter System
A simple CLI tool to convert numbers between bases 2-36.
"""

import sys
import re


def is_valid_base(base: int) -> bool:
    """Check if the base is valid (2-36)."""
    return 2 <= base <= 36


def is_valid_number(s: str) -> bool:
    """Check if the input string contains only valid digits for the given base."""
    if not s:
        return False
    # Define valid characters for bases 2-36
    valid_chars = re.compile(r'^[0-9A-Z]+$')
    return bool(valid_chars.match(s))


def convert_number(s: str, base: int) -> str:
    """
    Convert a string number from 'base' to decimal, then to the target base.
    Returns the string representation in the target base.
    """
    # 1. Validate Base
    if not is_valid_base(base):
        raise ValueError(f"Base must be between 2 and 36, got {base}")

    # 2. Validate Input String
    if not is_valid_number(s):
        raise ValueError(f"Invalid number format: '{s}'. Only digits 0-9 and A-Z are allowed.")

    # 3. Convert to Decimal
    decimal_value = 0
    for char in s:
        if char.isdigit():
            digit = int(char)
        elif 'A' <= char <= 'Z':
            digit = ord(char) - ord('A') + 10
        else:
            raise ValueError(f"Invalid character '{char}' in number.")

        decimal_value = decimal_value * base + digit

    # 4. Convert from Decimal to Target Base
    if decimal_value == 0:
        return '0'

    digits = []
    while decimal_value > 0:
        remainder = decimal_value % base
        digits.append(str(remainder))
        decimal_value //= base

    # 5. Reverse to get correct order
    return ''.join(reversed(digits))


def main():
    if len(sys.argv) != 4:
        print("Usage: python base_converter.py <input_base> <output_base> <number>")
        print("Example: python base_converter.py 10 2 8")
        sys.exit(1)

    try:
        input_base = int(sys.argv[1])
        output_base = int(sys.argv[2])
        number_str = sys.argv[3]
    except ValueError:
        print("Error: Invalid input arguments.")
        sys.exit(1)

    try:
        result = convert_number(number_str, input_base)
        print(result)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
