def match_parens(lst):
    """
    You are given a list of two strings, both strings consist of open
    parentheses '(' or close parentheses ')' only.
    Your job is to check if it is possible to concatenate the two strings in
    some order, that the resulting string will be good.
    A string S is considered to be good if and only if all parentheses in S
    are balanced. For example: the string '(())()' is good, while the string
    '())' is not.
    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.

    Examples:
    match_parens(['()(', ')']) == 'Yes'
    match_parens([')', ')']) == 'No'
    """

    # Helper function to check if a string is balanced (properly nested)
    def is_balanced(s):
        open_count = 0
        close_count = 0
        for char in s:
            if char == '(':
                open_count += 1
            elif char == ')':
                close_count += 1
        return open_count == close_count

    def can_make_balanced(s1, s2):
        # We need to check if s1 + s2 is balanced OR s2 + s1 is balanced
        # We can simulate the process by iterating through s1, then s2
        # and maintaining a running balance.

        balance = 0
        for char in s1:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False

        # After s1, we must have a balance of 0 to be valid
        if balance != 0:
            return False

        # Now iterate through s2. If balance becomes negative at any point, it's invalid.
        # If we reach the end with balance 0, it's valid.
        for char in s2:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False

        return balance == 0

    s1, s2 = lst
    return can_make_balanced(s1, s2)

