from typing import List


def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    # Validate that inputs are strings
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Both arguments must be strings.")

    # Validate that inputs contain only '0' and '1'
    if not all(c in '01' for c in a) or not all(c in '01' for c in b):
        raise ValueError("Inputs must consist only of '0' and '1'.")

    # Validate that inputs are of equal length
    if len(a) != len(b):
        raise ValueError("Input strings must be of equal length.")

    # Perform binary XOR
    # '1' if bits differ, '0' if bits are the same
    result = [
        '1' if bit_a != bit_b else '0' 
        for bit_a, bit_b in zip(a, b)
    ]

    return "".join(result)

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if not isinstance(n, int):
        raise TypeError(f"Expected an integer, got {type(n).__name__}")

    if n < 0:
        return ""

    result = []
    for i in range(n + 1):
        result.append(str(i))

    return " ".join(result)

