def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    # Base case: 0 or 1 element is always monotonic
    if len(l) <= 1:
        return True

    # Determine the direction from the first two elements
    if l[0] < l[1]:
        # Non-decreasing (increasing or equal)
        # Check that every subsequent element is >= the previous one
        for i in range(1, len(l) - 1):
            if l[i] > l[i+1]:
                return False
        return True
    elif l[0] > l[1]:
        # Non-increasing (decreasing or equal)
        # Check that every subsequent element is <= the previous one
        for i in range(1, len(l) - 1):
            if l[i] < l[i+1]:
                return False
        return True
    else:
        # Constant sequence (all elements equal)
        # Check that every subsequent element is == the previous one
        for i in range(1, len(l) - 1):
            if l[i] != l[i+1]:
                return False
        return True

def correct_bracketing(brackets: str) -> bool:
    """
    Validates if every opening bracket has a corresponding closing bracket.

    Args:
        brackets (str): A string containing only '(' and ')'.

    Returns:
        bool: True if the brackets are balanced, False otherwise.
    """
    # Edge case: Empty string is considered balanced
    if not brackets:
        return True

    stack = []

    for char in brackets:
        if char == '(':
            stack.append(1) # Use integer for efficiency
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        else:
            # STRICT VALIDATION: Input must only contain '(' and ')'
            raise ValueError(f"Invalid character '{char}' found in input string.")

    return len(stack) == 0

