def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    Shift amount = 2 * 2 = 4
    """
    shift = 2 * 2
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    upper_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    # Pre-compute translation tables for O(1) lookup
    lower_map = {char: alphabet[(alphabet.index(char) + shift) % 26] for char in alphabet}
    upper_map = {char: upper_alphabet[(upper_alphabet.index(char) + shift) % 26] for char in upper_alphabet}

    result = []

    for char in s:
        if char in lower_map:
            result.append(lower_map[char])
        elif char in upper_map:
            result.append(upper_map[char])
        else:
            # Keep non-alphabetic characters unchanged
            result.append(char)

    return "".join(result)

