    Given a dictionary, return True if all keys are strings in lower 
    case or all keys are strings in upper case, else return False.
    The function should return False is the given dictionary is empty.
    """
    # Constraint: Return False if dictionary is empty
    if not d:
        return False

    # Check if all keys are strings
    if not all(isinstance(key, str) for key in d.keys()):
        return False

    # Determine the expected case based on the first key
    first_key = next(iter(d.keys()))

    # Check if the first key is lowercase or uppercase
    if first_key.islower():
        # All keys must be lowercase
        return all(key.islower() for key in d.keys())
    elif first_key.isupper():
        # All keys must be uppercase
        return all(key.isupper() for key in d.keys())
    else:
        # If the first key is neither (e.g., mixed case like "Name"), return False
        return False

from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty input or None gracefully
    if not test:
        return {}

    # FIX: Split the string by spaces to get individual letters
    # This ensures spaces are treated as delimiters, not data points
    letters = test.split()

    # Use Counter for O(n) counting
    counts = Counter(letters)

    # Find the maximum frequency
    max_count = max(counts.values())

    # Filter and return only keys with the max frequency
    return {char: count for char, count in counts.items() if count == max_count}

def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.

    The Collatz conjecture is a conjecture in mathematics that concerns a sequence defined
    as follows: start with any positive integer n. Then each term is obtained from the 
    previous term as follows: if the previous term is even, the next term is one half of 
    the previous term. If the previous term is odd, the next term is 3 times the previous
    term plus 1. The conjecture is that no matter what value of n, the sequence will always reach 1.

    Note: 
        1. Collatz(1) is [1].
        2. returned list sorted in increasing order.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    odd_numbers = []
    current = n

    while current > 0:
        if current % 2 != 0:
            odd_numbers.append(current)

        if current == 1:
            break

        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1

    return sorted(odd_numbers)

