def bf(planet1, planet2):
    '''
    Returns a tuple of planets between planet1 and planet2.
    Returns empty tuple if inputs are invalid or adjacent.
    '''
    # 1. Define the canonical list of planets
    planets = [
        "Mercury", "Venus", "Earth", "Mars", 
        "Jupiter", "Saturn", "Uranus", "Neptune"
    ]

    # 2. Validate inputs
    if planet1 not in planets or planet2 not in planets:
        return ()

    # 3. Get indices
    try:
        idx1 = planets.index(planet1)
        idx2 = planets.index(planet2)
    except ValueError:
        # Fallback safety, though validated above
        return ()

    # 4. Determine range (ensure start < end)
    start = min(idx1, idx2)
    end = max(idx1, idx2)

    # 5. Extract intermediate planets (exclusive of start and end)
    # Python slice [start+1 : end]
    intermediate = planets[start + 1 : end]

    # 6. Return as tuple
    return tuple(intermediate)
