    'one three five'
    """

    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    num_to_word = {v: k for k, v in word_to_num.items()}

    if not numbers:
        return ""

    try:
        parsed_integers = [
            word_to_num[word.lower()] 
            for word in numbers.split()
        ]
    except KeyError:
        raise ValueError("Invalid number word found")

    sorted_integers = sorted(parsed_integers)

    # Note: We iterate backwards to ensure the join order is correct for the final output
    sorted_words = [num_to_word[num] for num in sorted_integers]

    return " ".join(sorted_words)
