def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input 'n' must be a positive integer.")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0:
            return False

        # Trial division for small numbers
        if num < 1000000:
            i = 3
            while i * i <= num:
                if num % i == 0:
                    return False
                i += 2
            return True

        # Miller-Rabin for larger numbers
        bases = [2, 3, 5, 7, 11, 13, 17, 19, 23]
        r, d = 0, num - 1
        while d % 2 == 0:
            r += 1
            d //= 2

        for a in bases:
            if a >= num:
                continue
            x = pow(a, d, num)
            if x == 1 or x == num - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, num)
                if x == num - 1:
                    break
            else:
                return False
        return True

    count = 0
    a, b = 0, 1

    while True:
        fib_num = a
        a, b = b, a + b

        if is_prime(fib_num):
            count += 1
            if count == n:
                return fib_num
