from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty string case immediately
    if not test:
        return {}

    # Split the input string by whitespace to get individual characters
    words = test.split()

    # Count the frequency of each character
    counts = Counter(words)

    # Find the maximum count value in the dictionary
    # Note: We assume counts is not empty because of the check above
    max_count = max(counts.values())

    # Create a new dictionary containing only the characters with the max_count
    # We iterate through items and filter based on the count value
    result = {}
    for char, count in counts.items():
        if count == max_count:
            result[char] = count

    return result
