    chars = test.split()

    if not chars:
        return {}

    # Count frequencies using a standard dictionary
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Determine the maximum frequency
    max_count = max(counts.values())

    # Filter the dictionary to include only characters with the maximum frequency
    return {char: count for char, count in counts.items() if count == max_count}
