def histogram(test):
    """
    Given a string representing a space separated lowercase letters, 
    return a dictionary of the letter with the most repetition and 
    containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    # Handle empty string or whitespace-only input immediately
    if not test or not test.strip():
        return {}

    # Split the string by spaces to get individual characters
    # This handles multiple spaces and leading/trailing whitespace correctly
    chars = test.split()

    # Safety check: if split results in an empty list (e.g., input was just spaces)
    if not chars:
        return {}

    # Count frequencies of each character
    counts = {}
    for char in chars:
        counts[char] = counts.get(char, 0) + 1

    # Find the maximum frequency value
    # Since we checked for empty chars, counts will not be empty here
    max_count = max(counts.values())

    # Filter characters that have the maximum frequency
    # We iterate through items and include only those matching max_count
    result = {}
    for char, count in counts.items():
        # Include the character if its count is greater than or equal to max_count
        # This ensures we capture all ties and the primary maximum
        if count >= max_count:
            result[char] = count

    return result

def valid_date(date):
    """
    Validates a date string in 'mm-dd-yyyy' format.

    Rules:
    1. Format must be mm-dd-yyyy with hyphens.
    2. Month: 1-12 (must be 2 digits).
    3. Day: 1-31 (must be 2 digits), 1-30 (Apr, Jun, Sep, Nov), 1-29 (Feb).
    4. Year: Must be 4 digits.
    5. Returns True if valid, False otherwise.
    """
    # 1. Basic Type and Empty Check
    if not isinstance(date, str) or not date:
        return False

    # 2. Format Check: Split by hyphen
    parts = date.split('-')
    if len(parts) != 3:
        return False

    # 3. Parse and Validate Numeric Content and Lengths
    try:
        month_str, day_str, year_str = parts

        # Strict format check: mm (2), dd (2), yyyy (4)
        if len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4:
            return False

        month = int(month_str)
        day = int(day_str)
        year = int(year_str) 
    except ValueError:
        return False

    # 4. Month Range Validation
    if month < 1 or month > 12:
        return False

    # 5. Day Range Validation (General)
    if day < 1:
        return False

    # 6. Contextual Day Validation based on Month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False
    elif month == 2:
        if day > 29:
            return False

    return True

def minPath(grid, k):
    """
    Finds the lexicographically smallest path of length k in the grid.
    Uses a greedy BFS approach to maintain the frontier of optimal positions.
    """
    if not grid or not grid[0]:
        return []

    n = len(grid)
    # Validate constraints as per requirements
    if n < 2 or k < 1:
        raise ValueError("Invalid grid dimensions or k value.")

    # Directions: Up, Down, Left, Right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Step 1: Find the global minimum value to start the path
    min_val = float('inf')
    for r in range(n):
        for c in range(n):
            if grid[r][c] < min_val:
                min_val = grid[r][c]

    # Initialize the frontier with all cells having the minimum value
    current_positions = set()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == min_val:
                current_positions.add((r, c))

    result = [min_val]

    # If k is 1, we are done
    if k == 1:
        return result

    # Iteratively build the path for k-1 more steps
    # We need to perform k-1 transitions to get a total of k cells
    for _ in range(k - 1):
        next_positions = set()
        min_next_val = float('inf')

        # Expand current frontier to neighbors
        for r, c in current_positions:
            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                # Check boundaries
                if 0 <= nr < n and 0 <= nc < n:
                    val = grid[nr][nc]
                    # Greedily find the smallest neighbor value
                    if val < min_next_val:
                        min_next_val = val
                        # Reset next_positions if we found a new minimum
                        next_positions = {(nr, nc)}
                    elif val == min_next_val:
                        next_positions.add((nr, nc))

        # Append the minimum value found for this step
        result.append(min_next_val)

        # Update frontier for the next iteration
        current_positions = next_positions

        # Safety break if no neighbors found (should not happen in valid grid)
        if not current_positions:
            break

    return result

def largest_smallest_integers(lst):
    """
    Returns a tuple (a, b), where 'a' is the largest negative integer 
    and 'b' is the smallest positive integer in the list.
    Returns None for any category if no such integers exist.

    Time Complexity: O(n)
    Space Complexity: O(1)
    """
    max_neg = None
    min_pos = None

    for num in lst:
        if num < 0:
            # Update largest negative (closest to 0)
            # We check if current is larger than max_neg to find the one closest to zero
            if max_neg is None or num >= max_neg:
                max_neg = num
        elif num > 0:
            # Update smallest positive (closest to 0)
            # We check if current is smaller than min_pos to find the one closest to zero
            if min_pos is None or num <= min_pos:
                min_pos = num

    return (max_neg, min_pos)
